use std::fs
use std::process

fn fail() {
    println("error")
    process::exit(1)
}

fn parse_row(line: string) -> Vec<int> {
    let mut out: Vec<int> = []
    for tok in line.split_whitespace() {
        match tok.parse::<int>() {
            Ok(v) => out.push(v),
            Err(_) => {
                fail()
            }
        }
    }
    out
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let lines: Vec<string> = text.lines().collect()
    if lines.len() < 1 {
        fail()
    }
    let head = parse_row(lines[0])
    if head.len() != 2 || head[0] < 1 || head[1] < 1 {
        fail()
    }
    let r: int = head[0]
    let c: int = head[1]
    if (lines.len() as int) < r + 1 {
        fail()
    }
    let mut grid: Vec<Vec<int>> = []
    let mut i: int = 0
    while i < r {
        let row = parse_row(lines[(i + 1) as usize])
        if (row.len() as int) != c {
            fail()
        }
        grid.push(row)
        i += 1
    }
    let mut top: int = 0
    let mut bot: int = r - 1
    let mut left: int = 0
    let mut right: int = c - 1
    let mut out: Vec<string> = []
    while top <= bot && left <= right {
        let mut j = left
        while j <= right {
            out.push("${grid[top as usize][j as usize]}")
            j += 1
        }
        top += 1
        j = top
        while j <= bot {
            out.push("${grid[j as usize][right as usize]}")
            j += 1
        }
        right -= 1
        if top <= bot {
            j = right
            while j >= left {
                out.push("${grid[bot as usize][j as usize]}")
                j -= 1
            }
            bot -= 1
        }
        if left <= right {
            j = bot
            while j >= top {
                out.push("${grid[j as usize][left as usize]}")
                j -= 1
            }
            left += 1
        }
    }
    println(out.join(" "))
}

